// blank-ocean.ts
/**
 * World Builder blank map - All ocean.
 */

import * as globals from "#base/maps/map-globals.js";

function requestMapData(initParams: MapInitializationParams) {
	engine.call("SetMapInitData", initParams);
}

function generateMap() {
	console.log("Generating blank ocean map");

	const iWidth = GameplayMap.getGridWidth();
	const iHeight = GameplayMap.getGridHeight();

	// Set every tile to ocean
	for (let y = 0; y < iHeight; y++) {
		for (let x = 0; x < iWidth; x++) {
			TerrainBuilder.setTerrainType(x, y, globals.g_OceanTerrain);
		}
	}
}

engine.on("RequestMapInitData", requestMapData);
engine.on("GenerateMap", generateMap);

console.log("Loaded blank-ocean.ts");
